128	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
129	        validateRequiredFields(ownerFieldsDto);
130	        HttpHeaders headers = new HttpHeaders();
131	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
132	        String address = normalizeAddress(ownerFieldsDto.getAddress());
133	        owner.setAddress(address);
134	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
135	            assignHousehold(owner, ownerFieldsDto.getLastName(), address);
136	        } else {
137	            rejectDuplicateHousehold(ownerFieldsDto.getLastName(), address);
138	        }
139	        String telephone = normalizeTelephone(ownerFieldsDto.getTelephone());
140	        rejectDuplicateTelephone(telephone);
141	        owner.setTelephone(telephone);
142	        owner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
143	        if (owner.getRegistrationDate() == null) {
144	            owner.setRegistrationDate(LocalDate.now());
